CREATE TABLE "AutomationRule" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"createdByMemberId" TEXT NOT NULL,"name" TEXT NOT NULL,"trigger" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'draft',"runMode" TEXT NOT NULL DEFAULT 'dry_run',"conditions" JSONB NOT NULL,"actions" JSONB NOT NULL,"runCount" INTEGER NOT NULL DEFAULT 0,"successCount" INTEGER NOT NULL DEFAULT 0,"failureCount" INTEGER NOT NULL DEFAULT 0,"lastRunAt" TIMESTAMP(3),"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AutomationRule_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE,CONSTRAINT "AutomationRule_createdByMemberId_fkey" FOREIGN KEY ("createdByMemberId") REFERENCES "WorkspaceMember"("id") ON DELETE CASCADE);
CREATE TABLE "AutomationRun" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"ruleId" TEXT NOT NULL,"eventKey" TEXT NOT NULL,"trigger" TEXT NOT NULL,"entityType" TEXT,"entityId" TEXT,"status" TEXT NOT NULL DEFAULT 'started',"context" JSONB,"actionResults" JSONB,"errorCode" TEXT,"errorMessage" TEXT,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "AutomationRun_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE,CONSTRAINT "AutomationRun_ruleId_fkey" FOREIGN KEY ("ruleId") REFERENCES "AutomationRule"("id") ON DELETE CASCADE,UNIQUE("ruleId","eventKey"));
CREATE TABLE "OperationalSnapshot" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"status" TEXT NOT NULL,"metrics" JSONB NOT NULL,"issues" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OperationalSnapshot_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE INDEX "AutomationRule_workspaceId_status_trigger_idx" ON "AutomationRule"("workspaceId","status","trigger"); CREATE INDEX "AutomationRule_workspaceId_updatedAt_idx" ON "AutomationRule"("workspaceId","updatedAt"); CREATE INDEX "AutomationRun_workspaceId_status_startedAt_idx" ON "AutomationRun"("workspaceId","status","startedAt"); CREATE INDEX "AutomationRun_workspaceId_trigger_startedAt_idx" ON "AutomationRun"("workspaceId","trigger","startedAt"); CREATE INDEX "AutomationRun_entityType_entityId_startedAt_idx" ON "AutomationRun"("entityType","entityId","startedAt"); CREATE INDEX "OperationalSnapshot_workspaceId_createdAt_idx" ON "OperationalSnapshot"("workspaceId","createdAt"); CREATE INDEX "OperationalSnapshot_status_createdAt_idx" ON "OperationalSnapshot"("status","createdAt");
